@Composable private fun Core(p:Float,phase:BreathPhase,size:androidx.compose.ui.unit.Dp){val breathing=when(phase){BreathPhase.INHALE->.78f+.22f*p;BreathPhase.EXHALE->1f-.22f*p;else->1f};val loop=rememberInfiniteTransition(label="core_pulse");val pulse by loop.animateFloat(1f,1.045f,infiniteRepeatable(tween(1050,easing=FastOutSlowInEasing),RepeatMode.Reverse),label="hold_pulse");val q=breathing*if(phase==BreathPhase.HOLD_AFTER_INHALE||phase==BreathPhase.HOLD_AFTER_EXHALE)pulse else 1f;Canvas(Modifier.size(size)){val r=min(this.size.width,this.size.height)*.38f*q;repeat(6){i->drawCircle(LumyrinthColor.VioletBright.copy(alpha=.5f-i*.06f),r+i*12,center,style=Stroke(2f))};drawCircle(LumyrinthColor.Magenta,r*.12f,center)}}
